import com.limelight.binding.audio.*;
import java.security.MessageDigest;

/** Actual production JNI bridge and player; generated bytes and fake output only. */
public final class MatBridgeProbe {
    private static native boolean deliver(MatCarrierConsumer consumer, byte[] cycle, boolean end);
    private static void check(boolean ok) { if (!ok) throw new AssertionError(); }
    public static void main(String[] args) throws Exception {
        System.load(args[0]);
        byte[] bytes = new byte[61440];
        for (int i = 8; i < bytes.length; i++) bytes[i] = (byte) (i * 31);
        bytes[0] = 0x72; bytes[1] = (byte) 0xf8; bytes[2] = 0x1f;
        bytes[3] = 0x4e; bytes[4] = 0x16; bytes[6] = 2;
        String expected = MatCarrierPlayer.hex(MessageDigest.getInstance("SHA-256").digest(bytes));
        for (int attempt = 0; attempt < 3; attempt++) {
            MatCarrierPlayer.Sink sink = new MatCarrierPlayer.Sink() {
                long words;
                public void start() {}
                public int write(short[] b, int offset, int count) {
                    int n = Math.min(count, 512); words += n; return n;
                }
                public long playedFrames() { return words / 8; }
                public void close() {}
            };
            try (MatPlaybackSession session = new MatPlaybackSession(sink)) {
                check(deliver(session, bytes, true));
                check(expected.equals(session.player().submittedSha256()));
                check(session.player().submittedBytes() == 61440);
            }
        }
        for (int mode = 0; mode < 2; mode++) {
            final boolean throwsError = mode == 1;
            MatCarrierConsumer rejected = new MatCarrierConsumer() {
                public boolean offerMatCycle(byte[] b,int n,long e,long d,long i,long pts) {
                    check(n == 61440 && e == 1 && d == 1 && i == 0 && pts == 0);
                    if (throwsError) throw new IllegalStateException("probe rejection");
                    return false;
                }
                public boolean endMatStream(long n) { throw new AssertionError("Unexpected EOS"); }
            };
            check(!deliver(rejected, bytes, true));
        }
        System.out.println("PASS production JNI delivery/hash/drain/reconnect/rejection/exception; fake sink only");
    }
}
